<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-2xl border bg-white"><div class="flex justify-between border-b p-6"><h2 class="text-lg font-semibold">Edit offplan payment</h2><button @click="close" class="border px-3">×</button></div><div v-if="loadingData" class="p-12 text-center">Loading…</div><form v-else @submit.prevent="submit"><div class="grid gap-4 p-6 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input"/></Field><Field label="Payment status"><select v-model="form.payment_status" class="input"><option>pending</option><option>paid</option><option>failed</option><option>cancelled</option><option>refunded</option></select></Field><Field label="Payment method"><input v-model="form.payment_method" class="input"/></Field><Field label="Paid at"><input v-model="form.paid_at" type="datetime-local" class="input"/></Field><Field label="Due date"><input v-model="form.due_date" type="date" class="input"/></Field><Field label="Application ID"><input v-model.number="form.application" type="number" class="input"/></Field><Field label="Payment plan ID"><input v-model.number="form.payment_plan" type="number" class="input"/></Field></div><div v-if="error" class="mx-6 mb-4 border border-red-200 bg-red-50 p-3 text-red-700">{{error}}</div><div class="flex justify-end gap-3 border-t p-4"><button type="button" @click="close" class="border px-5 py-2.5">Cancel</button><button :disabled="saving" class="bg-primary px-5 py-2.5 text-white">{{saving?'Saving…':'Save changes'}}</button></div></form></div></div></template><script>import OffplanField from "../offplan property/OffplanField.vue";const blank={amount:"",payment_status:"pending",payment_method:"getremit",transaction_id:"",paid_at:"",due_date:"",notes:"",application:0,payment_plan:0};export default{name:"EditOffplanPayment",components:{Field:OffplanField},props:{open:Boolean,id:[String,Number]},data(){return{form:{...blank},loadingData:false,saving:false,error:"",textFields:["amount","transaction_id","notes"]}},watch:{open(v){if(v)this.load()}},methods:{close(){if(!this.saving)this.$emit("close")},label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},async load(){this.loadingData=true;try{const r=await this.$apiGetById("/get_offplan_payment",this.id);this.form={...blank,...(r?.data?.data||r?.data||r?.payment||r)}}catch(e){this.error=e?.message||"Unable to load payment."}finally{this.loadingData=false}},async submit(){this.saving=true;try{await this.$apiPatch("/update_offplan_payment",this.id,{...this.form,application:Number(this.form.application),payment_plan:Number(this.form.payment_plan)});this.$emit("saved");this.close()}catch(e){this.error=e?.message||"Unable to update payment."}finally{this.saving=false}}}};</script><style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.625rem .75rem;outline:none}</style>